from lib import *
S = SS('u124')
R = J('u124'); ps = R['pick_stats']; ms = R['make_stats']
steps = [
    step(f"MIR(中级中间表示)是编译器在类型检查之后用的控制流图:pub fn pick(x: i32) -> i32 {{ if x > 10 {{ x * 2 }} else {{ x + 1 }} }} 的 MIR 有 {ps[0]} 个基本块(bb0–bb5)和临时变量 _0(返回值)、_1(参数 x)、_2…_4。bb0 里 _2 = Gt(copy _1, const 10_i32),终结符 switchInt(move _2) -> [0: bb3, otherwise: bb1] 做分支。", t=tl(S(1)), done=lidx(S(1), 'bb0', 'switchInt', 'fn pick'), kv=KV([['基本块', f'{ps[0]} 个'], ['switchInt', f'{ps[1]} 次(if 的分支)'], ['局部变量', '_0 返回值、_1 参数']], ['switchInt'])),
    step(f"debug 构建的整数溢出检查就写在 MIR 里:x * 2 被降低成 MulWithOverflow 再跟一个 assert(!move (_3.1: bool), \"attempt to compute `{{}} * {{}}`, which would overflow\", …) -> [success: bb2, unwind continue];x + 1 同理(AddWithOverflow + assert)。这个函数里一共 {ps[2]} 个 assert,失败走 unwind,成功才继续。", t=tl(S(1)), mark=lidx(S(1), 'MulWithOverflow', 'AddWithOverflow', 'assert('), kv=KV([['x * 2', 'MulWithOverflow + assert'], ['assert 失败', 'panic(unwind)']], ['x * 2'])),
    step(f"所有权与 drop 在 MIR 里是显式的:make 里 let s = String::from(\"hello\") 之后,正常路径末尾有 drop(_2) -> [return: bb4, unwind continue](函数结束时释放 s);而中间可能 panic 的调用(String::len、加法 assert)都带 unwind: bb5,bb5 是一个 (cleanup) 块:drop(_2) 再 resume —— panic 展开时也要释放 String。整个函数 {ms[0]} 个 drop 终结符,{ms[2]} 个 cleanup 块。", t=tl(S(2)), done=lidx(S(2), 'drop(_2)'), mark=lidx(S(2), 'cleanup', 'resume'), kv=KV([['正常路径', 'drop(_2) → return'], ['unwind 路径', 'bb5 (cleanup):drop(_2) → resume']], ['unwind 路径'])),
    step("MIR 优化:同一个函数 folded() { let a = 2 + 3; let b = a * 4; let unused = 99; b },mir-opt-level=0 时是 42 行:大量 StorageLive/StorageDead,AddWithOverflow(const 2, const 3) 与 MulWithOverflow 后跟 assert;mir-opt-level=2 只剩 16 行:bb0 里 _0 = const 20_i32; return; —— 常量折叠把 2 + 3、* 4 全算好了,溢出 assert 与没用的变量都消失了(调试信息里 a、b、unused 变成常量 5、20、99)。", t=tl(S(3)), mark=lidx(S(3), 'mir-opt-level=0', 'mir-opt-level=2'), done=lidx(S(3), '_0 = const 20_i32'), b=bars([['mir-opt-level=0', 42, '42 行'], ['mir-opt-level=2', 16, '16 行']], 42, cur=[0], done=[1]), kv=KV([['opt-level 0', '42 行,有溢出 assert'], ['opt-level 2', '16 行,_0 = const 20']], ['opt-level 2'])),
    step("借用检查也建立在 MIR 之上,但它的报告对用户来说是三个位置:v.push(4) 时报 error[E0502]: cannot borrow `v` as mutable because it is also borrowed as immutable,用箭头标出「immutable borrow occurs here」(&v[0])、「mutable borrow occurs here」(v.push)、「immutable borrow later used here」(println 里的 first)。借用的存活范围由 MIR 的控制流决定。", t=tl(S(4)), mark=lidx(S(4), 'error[E0502]', 'immutable borrow occurs here', 'mutable borrow occurs here', 'later used here'), kv=KV([['不可变借用', '&v[0]'], ['可变借用', 'v.push(4)'], ['后续使用', 'println!(first)']], ['后续使用'])),
]
A = mkart('u124', 124, 'Rust,MIR,编译器,中间表示,真实验证,动画演示',
    f'用 --emit=mir 看真实的 MIR:带分支函数的 {ps[0]} 个基本块与 switchInt;溢出检查是 MIR 里的 MulWithOverflow + assert;String 的 drop 与 panic 时的 cleanup 块;mir-opt-level 0 → 2 把函数从 42 行折叠成 _0 = const 20(16 行);借用错误的三个位置。',
    'MIR 是 Rust 编译器里最重要的中间层:借用检查、优化、单态化都围绕它。这篇让 rustc 把 MIR 打印出来,逐行读基本块、溢出断言、drop 与 unwind 路径,再看常量折叠怎样把它缩小。',
    [(f'{ps[0]} 个', 'pick 函数的基本块数'), ('42 → 16 行', 'folded() 在 mir-opt-level 0 与 2 下的 MIR 行数'), (f'{ms[2]} 个', 'make 函数里 panic 清理(cleanup)块的数量')],
    [('基本块与终结符', '<p>MIR 在编译流水线中的位置见<a href="rust-compile-stages.html">Rust 编译阶段</a>;MIR 之后是<a href="rust-llvm-ir-optimization.html">LLVM IR 与优化</a>。输出用 RUSTC_BOOTSTRAP=1,MIR 的文本格式随版本变化。</p>'), ('drop 与 unwind', '<p>Drop 的语义见<a href="rust-drop-trait.html">Drop Trait 与资源释放</a>。</p>'), ('MIR 优化', None), ('借用检查', '<p>借用规则见<a href="rust-shared-vs-mut-borrow.html">不可变借用与可变借用</a>。</p>')],
    steps, [ENV_U + '。MIR 来自 rustc --emit=mir(去掉 debuginfo);优化级别用 -Z mir-opt-level 切换', '没有验证:borrowck 使用的 MIR 版本(优化前)与 -Z dump-mir 各阶段的差别、MIR 解释器 Miri(需要 nightly)、泛型函数的 MIR 在单态化前后的区别、async fn 的 coroutine MIR'], 'MIR')
